protected final URL NDXOPKUrl(CustQuotationTrans _custQuotationTrans)
{
    ItemId  localItemId;
    InventTable lInventTable;
    URL localUrl ="";

    if (_custQuotationTrans.ProjTransType == QuotationProjTransType::Item)
    {
        lInventTable = InventTable::find(_custQuotationTrans.ItemId);
        localUrl = NDXMagentoBase::getItemOPKWEBAddress(lInventTable.NDXModelNumber, new xInfo().language());
    }

    return localUrl;
}

protected SalesQuotationDetailsTmp initializeSalesQuotationDetailsTmp(
    CustQuotationJour    _custQuotationJour,
    CustQuotationTrans   _custQuotationTrans,
    CustFormletterDocument      _custFormletterDocument)
{
    SalesQuotationDetailsTmp avaSalesQuotationTmp = next initializeSalesQuotationDetailsTmp(_custQuotationJour, _custQuotationTrans, _custFormletterDocument);
    avaSalesQuotationTmp.NDXOPKUrl   = this.NDXOPKUrl(_custQuotationTrans);

    return avaSalesQuotationTmp;
}
